begin;
select plan(25);
update public.bookmark_jobs set state='paused';
insert into public.threads(id,url,title,host,type,state) values(900000000000001,'https://example.com/recommend','DB source title','https://example.com','normal','inbox');
insert into public.bookmark_collections(id,name) values('dddddddd-9000-4000-8000-000000000001','Recommend target');
set local role authenticated;
select set_config('request.jwt.claim.sub','480f5282-7933-4800-a970-d6bc8f05e8cb',true);
select lives_ok($$select public.bookmark_command('recommend','{"threadId":"900000000000001","title":"Edited title","requestId":"aaaaaaaa-9000-4000-8000-000000000001"}')$$,'owner can request a recommendation before saving');
select is((select count(*) from public.bookmarks where source_thread_id=900000000000001),0::bigint,'request creates no bookmark');
select is((select scope->>'url' from public.bookmark_jobs where id='aaaaaaaa-9000-4000-8000-000000000001'),'https://example.com/recommend','URL is read from the source');
select is((select scope->>'sourceTitle' from public.bookmark_jobs where id='aaaaaaaa-9000-4000-8000-000000000001'),'DB source title','source title is preserved separately');
select lives_ok($$select public.bookmark_command('recommend','{"threadId":"900000000000001","title":"Edited title","requestId":"aaaaaaaa-9000-4000-8000-000000000001"}')$$,'same request resumes readback without duplication');
select throws_ok($$select public.bookmark_command('recommend','{"threadId":"900000000000001","title":"Different title","requestId":"aaaaaaaa-9000-4000-8000-000000000001"}')$$,'PT409','recommendation request changed','request ID cannot be reused for different input');
select is((select state from public.threads where id=900000000000001),'inbox','source state is unchanged');
select is((select scope->>'provider' from public.bookmark_jobs where id='aaaaaaaa-9000-4000-8000-000000000001'),'openrouter','new recommendation jobs record the selected API gateway');
reset role;
select ok(public.bookmark_worker_claim() is not null,'worker claims the draft recommendation');
select ok(public.bookmark_ai_reserve('eeeeeeee-9000-4000-8000-000000000001','aaaaaaaa-9000-4000-8000-000000000001',(select lease_token from public.bookmark_jobs where id='aaaaaaaa-9000-4000-8000-000000000001'),65536,2752512,'openrouter','typesafe/jev-1.13'),'recommendation uses the shared budget reservation');
select ok(public.bookmark_worker_commit('aaaaaaaa-9000-4000-8000-000000000001',(select lease_token from public.bookmark_jobs where id='aaaaaaaa-9000-4000-8000-000000000001'),'{"state":"succeeded","completed":1,"reservationId":"eeeeeeee-9000-4000-8000-000000000001","reservationState":"settled","chargedNano":4200,"outputTokens":5,"recommendation":{"collectionId":"dddddddd-9000-4000-8000-000000000001","collectionVersion":1,"basis":"topic","confidence":0.6}}'),'worker stores a recommendation without saving');
select is((select state from public.bookmark_jobs where id='aaaaaaaa-9000-4000-8000-000000000001'),'succeeded','draft-only job is complete');
select is((select charged_nano from public.bookmark_ai_reservations where id='eeeeeeee-9000-4000-8000-000000000001'),4200::bigint,'known Jev usage is settled');
select is((select count(*) from public.bookmarks where source_thread_id=900000000000001),0::bigint,'completion still creates no bookmark');
set local role authenticated;
select public.bookmark_command('collectionRename','{"id":"dddddddd-9000-4000-8000-000000000001","version":1,"name":"Changed target"}');
select throws_ok($$select public.bookmark_command('save','{"url":"https://example.com/recommend","urlKey":"https://example.com/recommend","threadId":"900000000000001","expectedSourceUrl":"https://example.com/recommend","title":"Edited title","collectionId":"dddddddd-9000-4000-8000-000000000001","collectionVersion":1}')$$,'PT409','collection changed','save rejects a stale recommended target');
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',true);
select throws_ok($$select public.bookmark_command('recommend','{"threadId":"900000000000001","title":"Edited title","requestId":"aaaaaaaa-9000-4000-8000-000000000002"}')$$,'42501','owner required','non-owner cannot request recommendations');
select is((select count(*) from public.bookmark_jobs where kind='recommend'),0::bigint,'RLS hides recommendation jobs from non-owner');
reset role;
insert into public.bookmark_jobs(id,kind,state,scope,total,lease_token,lease_expires_at) values
 ('aaaaaaaa-9000-4000-8000-000000000002','recommend','processing','{"threadId":"900000000000001","url":"https://example.com/recommend","sourceTitle":"DB source title","officialTitle":null,"title":"Edited title"}',1,'cccccccc-9000-4000-8000-000000000002',now()+interval '90 seconds');
select ok(public.bookmark_ai_reserve('eeeeeeee-9000-4000-8000-000000000002','aaaaaaaa-9000-4000-8000-000000000002','cccccccc-9000-4000-8000-000000000002',65536,2752512,'openrouter','typesafe/jev-1.13'),'in-flight recommendation reserves the same shared ledger');
select ok(public.bookmark_worker_commit('aaaaaaaa-9000-4000-8000-000000000002','cccccccc-9000-4000-8000-000000000002','{"state":"succeeded","completed":1,"reservationId":"eeeeeeee-9000-4000-8000-000000000002","reservationState":"settled","chargedNano":4200,"outputTokens":5,"recommendation":{"collectionId":"dddddddd-9000-4000-8000-000000000001","collectionVersion":1,"basis":"topic","confidence":0.6}}'),'late result is recorded with known usage');
select is((select state from public.bookmark_jobs where id='aaaaaaaa-9000-4000-8000-000000000002'),'failed','renamed target invalidates an in-flight result');
select is((select completed from public.bookmark_jobs where id='aaaaaaaa-9000-4000-8000-000000000002'),0,'invalidated result is not counted as complete');
select is((select state from public.bookmark_ai_reservations where id='eeeeeeee-9000-4000-8000-000000000002'),'settled','known charge remains settled for an invalidated result');
update public.bookmark_jobs set state='processing',lease_token='cccccccc-9000-4000-8000-000000000003',lease_expires_at=now()-interval '1 second' where id='aaaaaaaa-9000-4000-8000-000000000002';
insert into public.bookmark_ai_reservations(id,job_id,month,reserved_nano,input_tokens) values
 ('eeeeeeee-9000-4000-8000-000000000003','aaaaaaaa-9000-4000-8000-000000000002',date_trunc('month',now() at time zone 'Asia/Seoul')::date,2752512,65536);
select is(public.bookmark_worker_claim(),null::jsonb,'expired recommendation is not sent twice after an unknown charge');
select is((select state from public.bookmark_ai_reservations where id='eeeeeeee-9000-4000-8000-000000000003'),'uncertain','crash retains its reserved cost');
select is((select state from public.bookmark_jobs where id='aaaaaaaa-9000-4000-8000-000000000002'),'paused','uncertain recommendation requires explicit resume');
select * from finish();
rollback;
